#include <functional>
#include <string>

enum class Outcome { Bump, Attack, OpenDoor, Descend, Move };
struct MoveResult { Outcome outcome; bool usedTurn; int x; int y; };

MoveResult tryMove(std::string& map, int width, int x, int y, int dx, int dy, const std::function<bool(int, int)>& monsterAt)
{
    const int height{ width > 0 ? static_cast<int>(map.size()) / width : 0 };
    const int tx{ x + dx }, ty{ y + dy };
    if (tx < 0 || ty < 0 || tx >= width || ty >= height) return { Outcome::Bump, false, x, y };
    char& tile{ map[static_cast<std::size_t>(ty * width + tx)] };
    if (tile == '#') return { Outcome::Bump, false, x, y };
    if (monsterAt(tx, ty)) return { Outcome::Attack, true, x, y };
    if (tile == '+') { tile = '.'; return { Outcome::OpenDoor, true, x, y }; }
    if (tile == '>') return { Outcome::Descend, true, tx, ty };
    return { Outcome::Move, true, tx, ty };
}

