// A 5 x 3 room:  #####
//                #.+>#
//                #####
static std::string room() { return "#####" "#.+>#" "#####"; }
static bool noMonsters(int, int) { return false; }
TEST("walk onto floor") { std::string m{ "....." }; const auto r{ tryMove(m, 5, 1, 0, 1, 0, noMonsters) }; CHECK(r.outcome == Outcome::Move); CHECK(r.usedTurn); CHECK_EQ(r.x, 2); }
TEST("bump into a wall") { std::string m{ room() }; const auto r{ tryMove(m, 5, 1, 1, -1, 0, noMonsters) }; CHECK(r.outcome == Outcome::Bump); CHECK(!r.usedTurn); CHECK_EQ(r.x, 1); }
TEST("the edge of the map is a wall") { std::string m{ "..." }; const auto r{ tryMove(m, 3, 0, 0, 0, -1, noMonsters) }; CHECK(r.outcome == Outcome::Bump); CHECK(!r.usedTurn); }
TEST("open a door") { std::string m{ room() }; const auto r{ tryMove(m, 5, 1, 1, 1, 0, noMonsters) }; CHECK(r.outcome == Outcome::OpenDoor); CHECK(r.usedTurn); CHECK_EQ(r.x, 1); CHECK_EQ(m[7], '.'); }
TEST("then walk through it") { std::string m{ room() }; tryMove(m, 5, 1, 1, 1, 0, noMonsters); const auto r{ tryMove(m, 5, 1, 1, 1, 0, noMonsters) }; CHECK(r.outcome == Outcome::Move); CHECK_EQ(r.x, 2); }
TEST("take the stairs") { std::string m{ "#.>#" }; const auto r{ tryMove(m, 4, 1, 0, 1, 0, noMonsters) }; CHECK(r.outcome == Outcome::Descend); CHECK_EQ(r.x, 2); }
TEST("attack instead of moving") { std::string m{ "..." }; const auto r{ tryMove(m, 3, 0, 0, 1, 0, [](int x, int y) { return x == 1 && y == 0; }) }; CHECK(r.outcome == Outcome::Attack); CHECK(r.usedTurn); CHECK_EQ(r.x, 0); }

